    [Id] [bigint] NOT NULL IDENTITY,
    [BusinessRole] [nvarchar](max),
    [ConflictingBusinessRole] [nvarchar](max),
    [TechnicalRole] [nvarchar](max),
    [ConflictingTechnicalRole] [nvarchar](max),
