    [ValidFrom] [datetime],
    [ValidTo] [datetime],
    [FileName] [nvarchar](max),
    [CreatedBy] [nvarchar](max),
    [CreatedDate] [datetime] NOT NULL,
    [LastModifiedBy] [nvarchar](max),
    [LastModifiedDate] [datetime],
    CONSTRAINT [PK_dbo.DI_SAP_SODConflictingRole] PRIMARY KEY ([Id])
)
END
